window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 10000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (fn()) return true; await sleep(150) } return false };
window.nav = (name) => [...document.querySelectorAll('nav button')].find((b) => b.textContent.trim() === name).click();
window.tab = async (label) => { const t = [...document.querySelectorAll('[role=tab]')].find((x) => x.textContent.trim() === label); if (!t) return 'NO TAB ' + label; t.click(); await sleep(800); return 'tab ' + label };
window.setInput = (input, value) => { const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; set.call(input, value); input.dispatchEvent(new Event('input', { bubbles: true })) };
window.slotEl = (k) => document.querySelector('[data-slot="' + k + '"]');
window.slotName = (k) => { const s = slotEl(k); const b = s && [...s.querySelectorAll('button')].find((x) => /dashboard/.test(x.title)); return b ? b.textContent : (s ? 'OPEN' : 'NONE') };
window.slots = () => [0, 1, 2].map(slotName);
window.loaded = () => document.querySelectorAll('[data-metric]').length > 0 && !/Loading…/.test(document.querySelector('main').innerText);
window.pick = async (k, text, match) => { const input = slotEl(k).querySelector('input'); input.focus(); setInput(input, text); await until(() => [...slotEl(k).querySelectorAll('[role=listbox] button')].some((b) => b.textContent.includes(match)), 12000); const b = [...slotEl(k).querySelectorAll('[role=listbox] button')].find((x) => x.textContent.includes(match)); if (!b) return 'NO MATCH ' + text + ' ' + JSON.stringify([...slotEl(k).querySelectorAll('[role=listbox] li')].map((l) => l.textContent).slice(0, 4)); b.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true })); await until(() => slotName(k) === match); await sleep(300); await until(loaded); return 'slot ' + k + ' = ' + slotName(k) };
window.remove = async (k) => { const b = slotEl(k).querySelector('button[aria-label^="Remove"]'); if (!b) return 'NO REMOVE'; const name = b.getAttribute('aria-label'); b.click(); await sleep(400); return name + ' -> ' + slotName(k) };
window.row = (id) => { const r = document.querySelector('[data-metric="' + id + '"]'); if (!r) return 'MISSING ' + id; return [...r.querySelectorAll('[data-cell]')].map((c) => { const v = c.querySelector('span').textContent; const lead = c.querySelector('[data-lead]') ? '*' : ''; const rank = c.lastElementChild.textContent; return v + lead + (rank ? ' (' + rank + ')' : '') }).join(' | ') };
window.rowTitles = (id) => { const r = document.querySelector('[data-metric="' + id + '"]'); return r ? [...r.querySelectorAll('[data-cell]')].map((c) => c.title.split('\n')[0]) : 'MISSING ' + id };
window.family = (label) => { const groups = [...document.querySelectorAll('[aria-label=Comparison] > div')]; const g = groups.find((x) => x.firstElementChild.firstElementChild.textContent === label); if (!g) return 'NO FAMILY ' + label; return [...g.querySelectorAll('[data-metric]')].map((r) => r.dataset.metric + ': ' + row(r.dataset.metric)) };
window.head = () => { const h = [...document.querySelectorAll('h1')].find((x) => x.textContent === 'Compare'); return h ? [...h.parentElement.children].slice(1).map((x) => x.textContent) : 'NO HEADING' };
window.leads = () => [0, 1, 2].map((k) => slotEl(k)?.innerText.match(/Leads \d+ of \d+/)?.[0] ?? '');
window.chooseSelect = async (title, value) => { const el = [...document.querySelectorAll('select')].find((x) => x.title === title); if (!el) return 'NO SELECT ' + title; Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set.call(el, String(value)); el.dispatchEvent(new Event('change', { bubbles: true })); await sleep(600); await until(loaded); return title + ' = ' + (el.selectedOptions[0]?.textContent ?? el.value) };
window.radio = async (name) => { const b = [...document.querySelectorAll('[role=radio]')].find((x) => x.textContent.trim() === name); if (!b) return 'NO RADIO ' + name; b.click(); await sleep(600); return 'radio ' + name };
window.openPlayer = async (name) => { const input = document.querySelector('input[aria-label="Search players"]'); setInput(input, name); await until(() => [...document.querySelectorAll('aside button')].some((x) => x.textContent.includes(name))); const b = [...document.querySelectorAll('aside button')].find((x) => x.textContent.includes(name)); if (!b) return 'NOT LISTED'; b.click(); await until(() => document.querySelector('h1')?.innerText.replace(/\n/g, ' ').includes(name.split(' ').pop())); return 'opened ' + document.querySelector('h1')?.innerText.replace(/\n/g, ' ') };
